SQL_DOC.P_SQL:
DECLARE
V_COUNT NUMBER; V_PO_NO KII_PO_KEPSUP.PO_NO%TYPE; V_PO_RELEASE_NO KII_PO_KEPSUP.PO_RELEASE_NO%TYPE; V_PO_LINE_NO KII_PO_KEPSUP.PO_LINE_NO%TYPE; V_PO_LOCATION_ID KII_PO_KEPSUP.PO_LOCATION_ID%TYPE;
BEGIN
V_COUNT := 0; V_PO_NO := SUBSTR($LEGACY_PO_NO$, 0, INSTR($LEGACY_PO_NO$,'-',1,1)-1); V_PO_RELEASE_NO := NVL(SUBSTR($LEGACY_PO_NO$, INSTR($LEGACY_PO_NO$,'-',-1,1)+1),0); V_PO_LINE_NO := SUBSTR($LEGACY_PO_SEQ$, 0, INSTR($LEGACY_PO_SEQ$,'-',1,1)-1); V_PO_LOCATION_ID := NVL(SUBSTR($LEGACY_PO_SEQ$, INSTR($LEGACY_PO_SEQ$,'-',-1,1)+1),0);
SELECT COUNT(*) INTO V_COUNT FROM KII_PO_KEPSUP WHERE PO_NO = TRIM(V_PO_NO) AND NVL(PO_RELEASE_NO,0) = NVL(TO_NUMBER(TRIM(V_PO_RELEASE_NO)),0) AND PO_LINE_NO = TRIM(V_PO_LINE_NO) AND NVL(PO_LOCATION_ID,0) = NVL(TO_NUMBER(TRIM(V_PO_LOCATION_ID)),0) ;
IF V_COUNT=0 THEN
INSERT INTO KII_PO_KEPSUP( PO_NO, PO_REVISION_NO, PO_RELEASE_NO, PO_RELEASE_REVISION_NO, PO_LINE_NO, PO_LOCATION_ID, SUPPLIER_NAME, SUPPLIER_PERSON_NAME, SUPPLIER_TELNO, SHIP_DATE, CREATION_DATE )VALUES( TRIM(V_PO_NO), 0, NVL(TO_NUMBER(TRIM(V_PO_RELEASE_NO)),0), 0, TRIM(V_PO_LINE_NO), NVL(TO_NUMBER(TRIM(V_PO_LOCATION_ID)),0), NVL(SUBSTRB(TRIM($SELLER_NAME$),1,20),' '), NVL(SUBSTRB(TRIM($SELLER_PERSON_NAME$),1,10),' '), NVL(SUBSTRB(TRIM($SELLER_TELNO$),1,15),' '), DECODE(TRIM($DS_DATE$),'X',NULL, TRIM($DS_DATE$)), SYSDATE );
ELSE
UPDATE KII_PO_KEPSUP SET SUPPLIER_NAME = NVL(SUBSTRB(TRIM($SELLER_NAME$),1,20),' '), SUPPLIER_PERSON_NAME = NVL(SUBSTRB(TRIM($SELLER_PERSON_NAME$),1,10),' '), SUPPLIER_TELNO = NVL(SUBSTRB(TRIM($SELLER_TELNO$),1,15),' '), SHIP_DATE = DECODE(TRIM($DS_DATE$),'X',NULL,TRIM($DS_DATE$)), CREATION_DATE = SYSDATE WHERE PO_NO = TRIM(V_PO_NO) AND NVL(PO_RELEASE_NO,0) = NVL(TO_NUMBER(TRIM(V_PO_RELEASE_NO)),0) AND PO_LINE_NO = TRIM(V_PO_LINE_NO) AND NVL(PO_LOCATION_ID,0) = NVL(TO_NUMBER(TRIM(V_PO_LOCATION_ID)),0) ;
END IF;
END;
